      if(pagePreviewPaths.has(page.previewPath))throw new Error(`Duplicate worksheet page preview path: ${page.previewPath}`);
      if(pagePdfPaths.has(page.pdfPath))throw new Error(`Duplicate worksheet page PDF path: ${page.pdfPath}`);
